import React, {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface DropdownItem {
  value: string;
  label: string;
  disabled?: boolean;
}

interface UseFilterOptionsReturn {
  filteredItems: DropdownItem[];
  activeValue: string;
  isActive: boolean; // true when dropdown is open and has matches
  clearFilter: () => void;
}

interface InputWithDropdownProps {
  /** Options to filter. Can be static or an async function (debounced). */
  options: DropdownItem[] | ((value: string) => Promise<DropdownItem[]>);
  /** Currently selected / typed value. Defaults to empty string. */
  value?: string;
  /** Callback when user selects an option from the dropdown. */
  onSelect: (value: string) => void;
  /** External control of value (optional). */
  onChange?: (value: string) => void;
  /** Placeholder text. */
  placeholder?: string;
  /** Number of debounce ms for async option loading. Default 300. */
  debounceMs?: number;
  /** Minimum characters before showing filtered results. Default 2. */
  minLength?: number;
  className?: string;
  id?: string;
  style?: React.CSSProperties;
  disabled?: boolean;
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

const DEBOUNCE_TIMEOUT = 300;

function debounce<T extends (...args: never[]) => void>(
  fn: T,
  ms: number,
): (...args: Parameters<T>) => void {
  let timer: ReturnType<typeof setTimeout>;
  return (...args: Parameters<T>) => {
    clearTimeout(timer);
    timer = setTimeout(() => fn(...args), ms);
  };
}

/**
 * Filter options by a prefix query. Optimized with early exit and array
 * filtering that skips already-matching items to avoid duplicates.
 */
function filterOptions(
  all: DropdownItem[],
  query: string,
  activeValue: string, // track what was previously selected so we can re-select
): DropdownItem[] {
  const q = query.toLowerCase();
  if (!q || q.length < 2) return [];

  // Skip items whose value already equals the current selection so we don't
  // show the same item twice when it also matches the prefix.
  return all.filter((item) => {
    if (item.value === activeValue) return false;
    return item.label.toLowerCase().startsWith(q);
  });
}

// ---------------------------------------------------------------------------
// Custom hook: filterable autocomplete options
// ---------------------------------------------------------------------------

function useFilterOptions(
  options: DropdownItem[] | ((value: string) => Promise<DropdownItem[]>>,
  query: string,
  activeValue: string,
  isOpen: boolean,
  minLength: number = 2,
  debounceMs: number = DEBOUNCE_TIMEOUT,
): UseFilterOptionsReturn {
  const [loadedOptions, setLoadedOptions] = useState<DropdownItem[]>(
    Array.isArray(options) ? [...options] : [],
  );

  // If options are provided as a function, fetch them once and cache.
  useEffect(() => {
    if (typeof options === "function") {
      (async () => {
        try {
          const res = await options(query);
          setLoadedOptions(res ?? []);
        } catch (err) {
          console.error("[useFilterOptions] failed to load options:", err);
          setLoadedOptions([]);
        }
      })();
    }
  }, [typeof options, options]);

  const debouncedQuery = useMemo(
    () => (query && !query.startsWith("/") ? query : ""), // "/" triggers full list
    [query, debounceMs],
    [_cb, debounceMs], // intentionally unused cb to keep memo stable
  );

  // Re-run filter whenever loaded options change or query changes.
  // We use a ref to avoid stale closures in useMemo.
  const queryRef = useRef(debouncedQuery);
  queryRef.current = debouncedQuery;

  const activeValueRef = useRef(activeValue);
  activeValueRef.current = activeValue;

  const filtered = useMemo(() => {
    const q = queryRef.current;
    const av = activeValueRef.current;
    if (!q || loadedOptions.length === 0) return [];
    return filterOptions(loadedOptions, q, av);
  }, [loadedOptions, q]);

  const isActive = useMemo(
    () => isOpen && filtered.length > 0,
    [isOpen, filtered.length],
  );

  const clearFilter = useCallback(() => {
    setLoadedOptions([]);
    queryRef.current = "";
    activeValueRef.current = "";
  }, []);

  return { filtered, activeValue, isActive, clearFilter };
}

// ---------------------------------------------------------------------------
// Sub-components
// ---------------------------------------------------------------------------

/** Small wrapper for each dropdown row. */
function OptionRow({
  item,
  isSelected,
  onSelect,
  disabled,
}: {
  item: DropdownItem;
  isSelected: boolean;
  onSelect: (value: string) => void;
  disabled?: boolean;
}) {
  return (
    <button
      type="button"
      className={[
        "option-row",
        isSelected && "option-row--selected",
        disabled && "option-row--disabled",
      ]
        .filter(Boolean)
        .join(" ")}
      onClick={() => !disabled && onSelect(item.value)}
      disabled={disabled}
      aria-selected={isSelected}
      title={item.label}
      style={{
        padding: "8px 12px",
        cursor: disabled ? "default" : "pointer",
        background: isSelected ? "#e8f0fe" : "transparent",
        border: "none",
        borderRadius: "4px",
        textAlign: "left",
        outline: "none",
        fontWeight: isSelected ? 600 : 400,
        color: disabled ? "#999" : "#1a1a1a",
        transition: "background 0.15s ease",
      }}
    >
      {item.label}
    </button>
  );
}

// ---------------------------------------------------------------------------
// Main Component
// ---------------------------------------------------------------------------

export function InputWithDropdown({
  options,
  value: controlledValue = "",
  onSelect,
  onChange,
  placeholder = "Search…",
  debounceMs = DEBOUNCE_TIMEOUT,
  minLength = 2,
  className,
  id,
  style,
  disabled = false,
}: InputWithDropdownProps) {
  const inputRef = useRef<HTMLInputElement>(null);
  const dropdownRef = useRef<HTMLDivElement>(null);
  const listboxRef = useRef<HTMLUListElement>(null);

  const [internalValue, setInternalValue] = useState(controlledValue);
  const [isOpen, setIsOpen] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Resolve options at render time (or via async function handled by hook).
  const resolvedOptions = useMemo(
    () => (Array.isArray(options) ? options : typeof options === "function" ? () => options(internalValue) : options),
    [options, internalValue],
  );

  const {
    filtered,
    activeValue,
    isActive,
    clearFilter,
  } = useFilterOptions(
    resolvedOptions,
    internalValue,
    activeValue,
    isOpen,
    minLength,
    debounceMs,
  );

  // --- Validation rules -------------------------------------------------------
  const validate = useCallback(
    (v: string) => {
      if (!v.trim()) return null; // empty is allowed if user wants to clear
      // Example rule: must start with a letter or contain a digit
      if (!/^[A-Za-z\d\s]+$/.test(v)) {
        return "Only letters, digits, and spaces are allowed.";
      }
      return null;
    },
    [],
  );

  const isValid = useMemo(() => !validate(internalValue), [internalValue, validate]);

  // --- Keyboard navigation ----------------------------------------------------
  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (disabled) return;

      switch (e.key) {
        case "ArrowDown":
          e.preventDefault();
          setIsOpen(true);
          inputRef.current?.focus();
          break;
        case "ArrowUp":
          e.preventDefault();
          setIsOpen(false);
          break;
        case "Enter":
          e.preventDefault();
          if (isActive && filtered.length) {
            onSelect(filtered[0].value); // pick first match
          } else if (!internalValue.trim() && !isActive) {
            // Enter when nothing typed → clear
            setInternalValue("");
            onChange?.("");
          }
          break;
        case "Escape":
          setIsOpen(false);
          break;
        case "Tab":
          // Keep focus in input on Tab unless menu is open & not focused
          if (isOpen && listboxRef.current?.contains(document.activeElement)) {
            e.preventDefault();
            // Focus last item
            const items = listboxRef.current.querySelectorAll<HTMLElement>(
              ".option-row",
            );
            const last = items[items.length - 1];
            last?.focus();
          }
          break;
        default:
          break;
      }
    },
    [disabled, isOpen, isActive, filtered, internalValue, onSelect, onChange],
  );

  // --- Close dropdown on outside click -----------------------------------------
  const handleOutsideClick = useCallback(() => {
    if (dropdownRef.current?.contains(document.activeElement)) return;
    setIsOpen(false);
  }, []);

  useEffect(() => {
    document.addEventListener("mousedown", handleOutsideClick);
    return () => document.removeEventListener("mousedown", handleOutsideClick);
  }, [handleOutsideClick]);

  // --- Focus management -------------------------------------------------------
  useEffect(() => {
    if (isOpen) {
      requestAnimationFrame(() => {
        inputRef.current?.focus();
        // Scroll first filtered item into view
        const first = listboxRef.current?.querySelector<HTMLElement>(".option-row");
        first?.scrollIntoView({ block: "nearest" });
      });
    }
  }, [isOpen]);

  // --- Sync external value when controlled -------------------------------------
  useEffect(() => {
    if (controlledValue !== undefined && controlledValue !== internalValue) {
      setInternalValue(controlledValue);
    }
  }, [controlledValue]);

  // --- Change handler ---------------------------------------------------------
  const handleChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const v = e.target.value;
      setInternalValue(v);
      setError(validate(v));

      if (onChange) onChange(v);

      // Clear filter on new input
      clearFilter();

      if (v.length >= minLength) {
        setIsOpen(true);
      } else {
        setIsOpen(false);
      }
    },
    [clearFilter, minLength, validate, onChange],
  );

  // --- Select handler ---------------------------------------------------------
  const handleSelectOption = useCallback(
    (val: string) => {
      setInternalValue(val);
      setError(validate(val));
      setIsOpen(false);
      onSelect(val);
      onChange?.(val);
    },
    [onSelect, onChange, validate],
  );

  // --- Compose final state for controlled usage -------------------------------
  const displayValue = controlledValue ?? internalValue;

  // --- Build error message for validation --------------------------------------
  const errorMsg = error ?? validate(displayValue);

  // --- Styles -----------------------------------------------------------------
  const inputStyle: React.CSSProperties = style
    ? { ...style }
    : {};

  return (
    <div
      className={`input-with-dropdown ${className ?? ""}`}
      style={{
        position: "relative",
        width: "100%",
      }}
    >
      {/* ---- Input field ---- */}
      <input
        ref={inputRef}
        id={id ?? "input-with-dropdown"}
        type="text"
        value={displayValue}
        placeholder={placeholder}
        disabled={disabled}
        onKeyDown={handleKeyDown}
        onChange={handleChange}
        autoComplete="off"
        aria-autocomplete="list"
        aria-expanded={isOpen}
        aria-controls={isOpen ? "dropdown-listbox" : undefined}
        aria-disabled={disabled}
        style={{
          ...inputStyle,
          width: "100%",
          padding: "10px 12px 10px 36px", // room for search icon
          fontSize: 14,
          lineHeight: 1.5,
          border: isValid
            ? "1px solid #d1d5db"
            : errorMsg
              ? "1px solid #ef4444"
              : "1px solid #9ca3af",
          borderRadius: 6,
          outline: "none",
          boxSizing: "border-box",
          transition: "border-color 0.2s ease",
          background: "#fff",
          boxShadow: "inset 0 1px 0 rgba(0,0,0,.05)",
        }}
      />

      {/* ---- Search icon / magnifier hint ---- */}
      <span
        className="search-icon"
        aria-hidden="true"
        style={{
          position: "absolute",
          left: 12,
          top: "50%",
          transform: "translateY(-50%)",
          color: "#9ca3af",
        }}
      >
        🔍
      </span>

      {/* ---- Error message ---- */}
      {errorMsg && (
        <p
          role="alert"
          className="error-msg"
          style={{
            margin: "4px 0 0",
            color: "#ef4444",
            fontSize: 12,
            lineHeight: 1.4,
          }}
        >
          {errorMsg}
        </p>
      )}

      {/* ---- Dropdown menu ---- */}
      {isActive && (
        <div
          ref={dropdownRef}
          role="listbox"
          id="dropdown-listbox"
          tabIndex={-1}
          className="dropdown-menu"
          style={{
            position: "absolute",
            top: "100%",
            left: 0,
            right: 0,
            zIndex: 1000,
            marginTop: 4,
            maxHeight: 280,
            overflowY: "auto",
            background: "#fff",
            border: "1px solid #e5e7eb",
            borderRadius: 6,
            boxShadow: "0 8px 24px rgba(0,0,0,.18)",
            padding: 0,
            outline: "none",
          }}
          onMouseDown={(e) => e.stopPropagation()}
        >
          <ul
            ref={listboxRef}
            role="list"
            style={{
              listStyle: "none",
              margin: 0,
              padding: 0,
            }}
          >
            {filtered.map((item) => (
              <OptionRow
                key={item.value}
                item={item}
                isSelected={activeValue === item.value}
                onSelect={handleSelectOption}
                disabled={disabled}
              />
            ))}

            {filtered.length === 0 && isOpen && (
              <li
                role="option"
                className="option-row--empty"
                style={{
                  padding: "12px 16px",
                  color: "#9ca3af",
                  fontSize: 13,
                  textAlign: "center",
                }}
              >
                No results found. Try a different term.
              </li>
            )}
          </ul>
        </div>
      )}
    </div>
  );
}

// ---------------------------------------------------------------------------
// Demo / Example usage
// ---------------------------------------------------------------------------

