Here is a reusable React/TypeScript autocomplete input. It supports controlled or uncontrolled values, optional validation, keyboard selection, outside-click dismissal, and a cap on rendered suggestions. For exceptionally large datasets, use server-side filtering or a virtualization library.

```tsx
import { useEffect, useMemo, useRef, useState } from "react";

interface InputProps {
  options: readonly string[];
  value?: string;
  onChange?: (value: string) => void;
  validate?: (value: string) => boolean;
  placeholder?: string;
  maxSuggestions?: number;
}

export function Input({
  options,
  value,
  onChange,
  validate,
  placeholder = "Type to search...",
  maxSuggestions = 100,
}: InputProps) {
  const controlled = value !== undefined;
  const [internalValue, setInternalValue] = useState("");
  const inputValue = controlled ? value : internalValue;

  const [isOpen, setIsOpen] = useState(false);
  const [activeIndex, setActiveIndex] = useState(-1);
  const containerRef = useRef<HTMLDivElement>(null);

  const normalizedOptions = useMemo(
    () => options.map((option) => ({ option, normalized: option.toLowerCase() })),
    [options],
  );

  const matches = useMemo(() => {
    const query = inputValue.trim().toLowerCase();
    if (!query) return [];

    const results: string[] = [];
    for (const item of normalizedOptions) {
      if (item.normalized.includes(query)) {
        results.push(item.option);
        if (results.length >= maxSuggestions) break;
      }
    }
    return results;
  }, [inputValue, maxSuggestions, normalizedOptions]);

  const isValid = validate ? validate(inputValue) : true;

  useEffect(() => {
    const handlePointerDown = (event: PointerEvent) => {
      if (!containerRef.current?.contains(event.target as Node)) {
        setIsOpen(false);
        setActiveIndex(-1);
      }
    };

    document.addEventListener("pointerdown", handlePointerDown);
    return () => document.removeEventListener("pointerdown", handlePointerDown);
  }, []);

  const updateValue = (nextValue: string) => {
    if (!controlled) setInternalValue(nextValue);
    onChange?.(nextValue);
  };

  const selectOption = (option: string) => {
    updateValue(option);
    setIsOpen(false);
    setActiveIndex(-1);
  };

  return (
    <div ref={containerRef} style={{ position: "relative", width: 300 }}>
      <input
        type="text"
        value={inputValue}
        placeholder={placeholder}
        onChange={(event) => {
          updateValue(event.target.value);
          setIsOpen(true);
          setActiveIndex(-1);
        }}
        onKeyDown={(event) => {
          if (!isOpen || matches.length === 0) return;

          if (event.key === "ArrowDown") {
            event.preventDefault();
            setActiveIndex((index) => (index + 1) % matches.length);
          } else if (event.key === "ArrowUp") {
            event.preventDefault();
            setActiveIndex((index) => (index <= 0 ? matches.length - 1 : index - 1));
          } else if (event.key === "Enter" && activeIndex >= 0) {
            event.preventDefault();
            selectOption(matches[activeIndex]);
          } else if (event.key === "Escape") {
            setIsOpen(false);
            setActiveIndex(-1);
          }
        }}
        aria-autocomplete="list"
        aria-expanded={isOpen && matches.length > 0}
        style={{
          boxSizing: "border-box",
